def resolve(path, cwd, links):
    # Normalize the starting path
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    # Split into components
    components = [c for c in remaining.split('/') if c and c != '.']

    links_followed = 0
    max_links = 8

    i = 0
    while i < len(components):
        component = components[i]

        if component == '..':
            # Move to parent
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
        else:
            # Append component
            if current == '/':
                current = '/' + component
            else:
                current = current + '/' + component

            # Check if this path is a symlink
            if current in links:
                links_followed += 1
                if links_followed > max_links:
                    return None

                target = links[current]

                # Determine the starting point for the target
                if target.startswith('/'):
                    current = '/'
                    target_components = [c for c in target[1:].split('/') if c and c != '.']
                else:
                    # Relative to the directory containing the link
                    if current == '/':
                        current = '/'
                    else:
                        current = current.rsplit('/', 1)[0]
                        if not current:
                            current = '/'
                    target_components = [c for c in target.split('/') if c and c != '.']

                # Replace the remaining components with target components + rest
                remaining_components = components[i + 1:]
                components = target_components + remaining_components
                i = 0
                continue

        i += 1

    # Return the result
    if current == '/':
        return '/'
    return current

